let mode=saved.mode,world=saved[mode].world,answers=saved[mode].answers,player={x:W*.5,y:H*.82},target=null,near=-1,keys=new Set(),moving=false,walkClock=0,face=1,activeNpc=-1,currentQuestion=-1,hasAnswered=false,ready=false,paused=false,lastTime=0,audioOn=false,audioCtx=null,toastTimer=null,mapFade=0,celebration=0,mapScene=null,backPortal=null;
