function queueNpcSave(){if(answers.length===L.TOTAL_QUESTIONS&&!runState().finishedAt)runState().finishedAt=Date.now();const npcCount=worlds.reduce((sum,w,m)=>sum+w.npcs.filter((_,n)=>isNpcDone(m,n)).length,0);saved.pendingUploads[runState().id+':'+npcCount]={id:runState().id,name:profile.name,gender:profile.gender,mode:'full',rulesVersion:L.RULES_VERSION,answers:[...answers],npcCount,score:points(),duration:duration(),mistakes:mistakesTotal()};persist();flushUploads();}
function flushUploads(){if(uploadPromise)return uploadPromise;uploadPromise=(async()=>{while(Object.keys(saved.pendingUploads).length){const [uploadKey,entry]=Object.entries(saved.pendingUploads)[0];try{$('sync-status').textContent='Đang lưu tiến độ…';const res=await fetch('/api/leaderboard',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)});if(!res.ok)throw new Error();delete saved.pendingUploads[uploadKey];persist();$('sync-status').textContent=`Đã lưu ${entry.npcCount}/${L.TOTAL_NPCS} NPC`;}catch{$('sync-status').textContent='Chưa lưu được. Bấm Thử lưu lại.';return false;}}return true;})().finally(()=>{uploadPromise=null;});return uploadPromise;}

const particles=Array.from({length:25},(_,i)=>({x:((i*73.13)%100)/100*W,y:((i*49.27)%100)/100*H,s:1+(i%4),phase:i*2.4}));
