function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function sound(type){if(!audioOn)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const notes=type==='win'?[523,659,784,1047]:type==='right'?[523,784]:type==='wrong'?[220,174]:[440];notes.forEach((hz,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(0,audioCtx.currentTime+i*.11);g.gain.linearRampToValueAtTime(.06,audioCtx.currentTime+i*.11+.02);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+i*.11+.24);o.connect(g);g.connect(audioCtx.destination);o.start(audioCtx.currentTime+i*.11);o.stop(audioCtx.currentTime+i*.11+.26);});}catch{}}
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error(src));im.src=src;});}
function splitSheet(im,cols,rows){const out=[];for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
 const cell=document.createElement('canvas');cell.width=Math.floor(im.width/cols);cell.height=Math.floor(im.height/rows);const cc=cell.getContext('2d');cc.drawImage(im,c*im.width/cols,r*im.height/rows,im.width/cols,im.height/rows,0,0,cell.width,cell.height);
 const pix=cc.getImageData(0,0,cell.width,cell.height).data;let x0=cell.width,y0=cell.height,x1=0,y1=0;for(let y=0;y<cell.height;y++)for(let x=0;x<cell.width;x++)if(pix[(y*cell.width+x)*4+3]>40){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}
 if(x1<x0){out.push(cell);continue;}const cut=document.createElement('canvas');cut.width=x1-x0+1;cut.height=y1-y0+1;cut.getContext('2d').drawImage(cell,x0,y0,cut.width,cut.height,0,0,cut.width,cut.height);out.push(cut);
 }return out;}
