function updateUI(){const lives=Math.max(0,3-runState().mistakes[world]);$('quiz-lives').textContent=`♥ ${lives}/3 lượt còn lại ở map này`;document.documentElement.style.setProperty('--accent',getWorld().color);canvas.setAttribute('aria-label',`Bản đồ ${getWorld().country}. Di chuyển bằng WASD hoặc phím mũi tên. Nhấn E để đối thoại.`);}
function changeMap(i){if(!Number.isInteger(i)||i<0||i>=worlds.length||!L.accessible(i,mode,answers))return false;world=i;if(mapScene)mapScene.setMap(i);player={x:W*.5,y:H*.82};target=null;near=-1;keys.clear();mapFade=1;persist();updateUI();$('interact').hidden=true;canvas.focus({preventScroll:true});return true;}
function goToNpc(i){if(!ready)return;const n=getWorld().npcs[i];target={x:n.pos[0]*W,y:n.pos[1]*H+90};canvas.focus({preventScroll:true});toast(`Đến ${n.zone}. Nhấn E khi ở gần.`);}
