function start(){const name=$('player-name').value.trim().replace(/\s+/g,' ');if(!name){$('name-error').textContent='Hãy nhập tên cho nhân vật trước khi bắt đầu.';$('player-name').focus();return;}if(profile&&(profile.name!==name||profile.gender!==selectedGender)){for(const m of ['full']){saved[m]={answers:[],world:0};runs[m]=newRun();}}profile={name:name.slice(0,24),gender:selectedGender};applyCharacter();mode='full';answers=[];world=0;runs[mode]=newRun();saved.started=true;persist();$('welcome').close();changeMap(0);toast('Chào '+profile.name+'! Bạn có 3 lượt sai ở mỗi map.');}
