function victory(){if(!runState().finishedAt){runState().finishedAt=Date.now();persist();}$('result-stats').textContent=`${profile.name} · ${points()} điểm · ${timeLabel(duration())} · ${mistakesTotal()} lần sai`;$('save-status').textContent=Object.values(saved.pendingUploads).some(e=>e.id===runState().id)?'Đang chờ lưu tiến độ.':'Tiến độ được tự lưu sau mỗi NPC.';$('save-score').textContent='Xem bảng xếp hạng';$('victory-copy').textContent='Bạn đã hoàn thành 90 câu hỏi và thu thập 18 ấn tri thức qua sáu vùng đất.';showDialog('victory');sound('win');}
async function loadRanking(){const ticket=++rankRequest;$('rank-body').replaceChildren();$('rank-status').textContent='Đang tải bảng xếp hạng…';try{const response=await fetch('/api/leaderboard');if(!response.ok)throw new Error();const rows=await response.json();if(ticket!==rankRequest)return;$('rank-status').textContent=rows.length?`Hành trình 90 câu · ${rows.length} thành tích`:'Chưa có thành tích. Hãy trở thành người đầu tiên!';rows.forEach((r,i)=>{const tr=document.createElement('tr');for(const text of [i+1,r.name,r.score,`${r.npc_count}/${L.TOTAL_NPCS}`,timeLabel(r.duration)]){const td=document.createElement('td');td.textContent=text;tr.append(td);}$('rank-body').append(tr);});}catch{if(ticket===rankRequest)$('rank-status').textContent='Chưa kết nối được bảng xếp hạng. Hãy bấm tải lại.';}}
