function openJournal(){$('journal-content').replaceChildren();worlds.forEach((w,m)=>{const title=document.createElement('h3');title.textContent=w.country+' · '+w.chapter.split(' · ')[0];$('journal-content').append(title);w.npcs.forEach((n,i)=>{const d=document.createElement('div');d.className='journal-entry'+(isNpcDone(m,i)?'':' journal-locked');const a=document.createElement('strong');a.textContent=(isNpcDone(m,i)?'✦ ':'◇ ')+n.name;const b=document.createElement('p');b.textContent=isNpcDone(m,i)?n.lesson:'Chưa mở khóa. Hoàn thành cuộc đối thoại tại '+n.zone+'.';d.append(a,b);$('journal-content').append(d);});});showDialog('journal');}
function rounded(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function drawCharacter(im,x,y,height,bob=0,flip=false){if(!im)return;const width=height*im.width/im.height;ctx.save();ctx.translate(x,y+bob);if(flip)ctx.scale(-1,1);ctx.drawImage(im,-width/2,-height,width,height);ctx.restore();}
function update(dt){if(modalOpen()||paused||!ready){moving=false;return;}let dx=0,dy=0;if(keys.has('w')||keys.has('arrowup'))dy--;if(keys.has('s')||keys.has('arrowdown'))dy++;if(keys.has('a')||keys.has('arrowleft'))dx--;if(keys.has('d')||keys.has('arrowright'))dx++;if(dx||dy)target=null;else if(target){const tx=target.x-player.x,ty=target.y-player.y,dist=Math.hypot(tx,ty);if(dist<5)target=null;else{dx=tx/dist;dy=ty/dist;}}
 moving=!!(dx||dy);if(moving){const len=Math.hypot(dx,dy);const step=Math.min(285*dt,target?Math.hypot(target.x-player.x,target.y-player.y):Infinity);player.x=Math.max(65,Math.min(W-65,player.x+dx/len*step));player.y=Math.max(H*.49,Math.min(H*.91,player.y+dy/len*step));if(Math.abs(dx)>.05)face=dx<0?-1:1;walkClock+=dt;}else walkClock=0;
 let nearest=-1,best=160;getWorld().npcs.forEach((n,i)=>{const d=Math.hypot(player.x-n.pos[0]*W,player.y-n.pos[1]*H);if(d<best){best=d;nearest=i;}});if(near!==nearest){near=nearest;$('interact').hidden=near<0;if(near>=0)$('interact').querySelector('span').textContent='Gặp '+getWorld().npcs[near].name;}
 if(backPortal&&backPortal.update({player,mapIndex:world,dt,changeMap}))return;
 if(isDone(world)&&player.y>H*.87&&Math.abs(player.x-W*.5)<95){target=null;player.y=H*.84;if(world===worlds.length-1)victory();else changeMap(world+1);}
}
function draw(t,dt){if(!ready)return;const w=getWorld();if(mapScene){mapScene.render(t);}else{ctx.clearRect(0,0,W,H);ctx.drawImage(assets.maps[world],0,0,W,H);if(!reduced){particles.forEach((p,i)=>{const x=(p.x+t*(8+i%4)+Math.sin(t*.5+p.phase)*13)%(W+20)-10,y=(p.y+t*(4+i%3))%H;ctx.save();ctx.globalAlpha=w.ambience==='leaves'?.5:.25+.2*Math.sin(t+p.phase);ctx.fillStyle=w.ambience==='leaves'?'#ffe4a0':'#d6eeff';ctx.translate(x,y);ctx.rotate(t*.5+p.phase);ctx.fillRect(0,0,p.s*2,p.s);ctx.restore();});}}
 if(target){ctx.strokeStyle='#fff4c3bb';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(target.x,target.y,12+Math.sin(t*4)*2,5,0,0,Math.PI*2);ctx.stroke();}
 const actors=getWorld().npcs.map((n,i)=>({type:'npc',i,y:n.pos[1]*H}));actors.push({type:'player',y:player.y});actors.sort((a,b)=>a.y-b.y);
 for(const a of actors){if(a.type==='player'){ctx.fillStyle='#09282050';ctx.beginPath();ctx.ellipse(player.x,player.y+3,22,8,0,0,Math.PI*2);ctx.fill();const frame=moving?Math.floor(walkClock*8)%4:1;drawCharacter(sprites.player[frame],player.x,player.y,100,!reduced&&moving?Math.sin(walkClock*16)*2:0,face<0);}else{const n=w.npcs[a.i],x=n.pos[0]*W,y=n.pos[1]*H,done=isNpcDone(world,a.i),active=true;ctx.fillStyle='#08232145';ctx.beginPath();ctx.ellipse(x,y+2,23,8,0,0,Math.PI*2);ctx.fill();if(near===a.i){ctx.strokeStyle='#ffe8a7';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x,y+3,34,12,0,0,Math.PI*2);ctx.stroke();}drawCharacter(sprites.npcs[n.sprite],x,y,105,!reduced?Math.sin(t*1.6+a.i)*1.6:0);
 ctx.font='600 19px GameSans, sans-serif';const label=(done?'✓ ':'')+n.name,tw=ctx.measureText(label).width;rounded(x-tw/2-15,y-150,tw+30,34,8,done?'#293e28ed':'#142722ed');ctx.fillStyle=done?'#f3d692':'#fff9e9';ctx.textAlign='center';ctx.fillText(label,x,y-127);if(!done&&active){const offset=!reduced?Math.sin(t*3)*4:0;rounded(x-13,y-195+offset,26,31,7,'#efcd85');ctx.fillStyle='#243528';ctx.font='bold 23px Georgia';ctx.fillText('!',x,y-172+offset);}
 }}
 if(backPortal)backPortal.draw(ctx,{mapIndex:world,time:t});
 if(isDone(world)){const x=W/2,y=H*.90;ctx.save();ctx.shadowColor='#f4d382';ctx.shadowBlur=22;ctx.strokeStyle='#ffe6a0';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(x,y,67+(reduced?0:Math.sin(t*3)*4),19,0,0,Math.PI*2);ctx.stroke();ctx.restore();rounded(x-122,y-58,244,33,8,'#142722ec');ctx.font='600 17px GameSans';ctx.fillStyle='#ffe9b4';ctx.textAlign='center';ctx.fillText(world===worlds.length-1?'Tháp Tri thức':'Cổng sang '+worlds[world+1].country,x,y-36);}
 if(celebration>0){celebration-=dt;if(!reduced)for(let i=0;i<35;i++){ctx.fillStyle=i%2?'#f5ce7f':'#cae8bb';const x=(i*79+t*30)%W,y=(i*83+(3-celebration)*240)%H;ctx.fillRect(x,y,5,5);}}
 if(mapFade>0){mapFade=Math.max(0,mapFade-dt*1.8);ctx.fillStyle=`rgba(10,20,27,${mapFade})`;ctx.fillRect(0,0,W,H);}
}
function loop(ms){const dt=Math.min((ms-lastTime)/1000,.04);lastTime=ms;update(dt);draw(ms/1000,dt);requestAnimationFrame(loop);}
canvas.addEventListener('pointerdown',e=>{if(!ready||modalOpen())return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;target={x:Math.max(65,Math.min(W-65,x)),y:Math.max(H*.49,Math.min(H*.91,y))};canvas.focus({preventScroll:true});});
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(modalOpen()){if($('quiz').open&&['1','2','3'].includes(k)){e.preventDefault();answerQuestion(Number(k)-1);}return;}if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright',' '].includes(k)){e.preventDefault();keys.add(k);}if(e.repeat)return;if(k==='e'){e.preventDefault();openNpc(near);}if(k==='j')openJournal();});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();target=null;});document.addEventListener('visibilitychange',()=>{paused=document.hidden;keys.clear();});
for(const b of document.querySelectorAll('[data-dir]')){const k={up:'w',down:'s',left:'a',right:'d'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(k);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(k));}
$('interact').onclick=()=>openNpc(near);$('quiz-close').onclick=()=>closeDialog('quiz');$('journal-btn').onclick=openJournal;$('start-full').onclick=()=>start();
$('choose-male').onclick=()=>chooseGender('male');$('choose-female').onclick=()=>chooseGender('female');$('resume-game').onclick=()=>closeDialog('welcome');$('retry-run').onclick=()=>closeDialog('game-over');$('leaderboard-btn').onclick=openRanking;$('rank-refresh').onclick=()=>loadRanking();$('save-score').onclick=saveScore;$('retry-save').onclick=()=>flushUploads();window.addEventListener('online',()=>flushUploads());for(const id of ['welcome','game-over'])$(id).addEventListener('cancel',e=>e.preventDefault());
$('victory-journal').onclick=()=>{closeDialog('victory');openJournal();};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>keys.clear()));
async function init(){try{if(document.fonts){await document.fonts.load("19px GameSans");}try{const {createMapScene}=await import('./triet-hanh-map-animation/map-scene.js');mapScene=await createMapScene(canvas,{map:world,autoStart:false,reducedMotion:reduced});}catch(err){console.warn('Map animation fallback',err);}try{const {BackPortal}=await import('./back-portal.js');backPortal=new BackPortal({width:W,height:H,mapNames:worlds.map(w=>w.country),font:'GameSans, system-ui, sans-serif',reducedMotion:reduced});}catch(err){console.warn('BackPortal fallback',err);}const spriteUrls=['assets/student-male.webp','assets/philosophers.png','assets/student-female.webp','assets/philosophers-extra.webp'];const loadPromises=mapScene?spriteUrls.map(loadImage):[...worlds.map(w=>loadImage('assets/'+w.file)),...spriteUrls.map(loadImage)];const results=await Promise.all(loadPromises);const spriteResults=mapScene?results:results.slice(worlds.length);if(!mapScene)assets.maps=results.slice(0,worlds.length);assets.explorer=spriteResults[0];assets.npcs=spriteResults[1];sprites.male=splitSheet(assets.explorer,4,1);sprites.female=splitSheet(spriteResults[2],4,1);document.documentElement.style.setProperty('--male-ratio',String(assets.explorer.width/4/assets.explorer.height));document.documentElement.style.setProperty('--female-ratio',String(spriteResults[2].width/4/spriteResults[2].height));applyCharacter();sprites.npcs=[...splitSheet(assets.npcs,4,3),...splitSheet(spriteResults[3],3,2)];ready=true;flushUploads();$('loading').hidden=true;updateUI();if(!saved.started||!profile)showStart();else toast('Chào mừng trở lại. Hành trình của bạn đã được lưu.');requestAnimationFrame(loop);}catch(e){$('loading').replaceChildren();const div=document.createElement('div');div.textContent='Chưa tải được bản đồ. Kiểm tra kết nối rồi thử lại.';const b=document.createElement('button');b.className='primary';b.textContent='Tải lại';b.onclick=()=>location.reload();div.append(b);$('loading').append(div);}}
// Optional browser agent access: same navigation and progress used by the UI.
window.PhiloGame={getProgress:()=>({mode,world,country:getWorld().country,answered:answers.length,total:L.TOTAL_QUESTIONS,unlocked:worlds.map((_,i)=>L.accessible(i,mode,answers))}),navigateMap:i=>changeMap(i)};
if(document.modelContext?.registerTool){for(const tool of [{name:'read_philosophy_game_progress',description:'Read current game mode, map and completed question count.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.PhiloGame.getProgress()},{name:'navigate_philosophy_game_map',description:'Navigate to an unlocked map, numbered zero through five. Does not answer questions or unlock maps.',inputSchema:{type:'object',properties:{map:{type:'integer',minimum:0,maximum:5}},required:['map'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.map)||input.map<0||input.map>=worlds.length)throw new Error('Invalid map');if(modalOpen())throw new Error('Close current dialogue first');if(!changeMap(input.map))throw new Error('Map is locked');return window.PhiloGame.getProgress();}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
updateUI();init();
